input.command:
for f in $(cat "$TMPDIR/timer_spinlock_files.txt"); do
  python3 - "$f" << 'PYEOF'
import re, sys
path = sys.argv[1]
src = open(path, errors='ignore').read()
lines = src.split('\n')
# find timer callback function names via timer_setup(&x->t, cb, ...) or setup_timer(&t, cb, ...)
cbs = set()
for m in re.finditer(r'timer_setup\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
for m in re.finditer(r'setup_timer\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
for m in re.finditer(r'setup_deferrable_timer\s*\(\s*&[\w\.\>\-\>\[\]]+,\s*(\w+)\s*,', src):
    cbs.add(m.group(1))
if not cbs:
    sys.exit()
# find lock names in those callback bodies
def body(name):
    m = re.search(r'(?:^|\n)[ \t]*(?:static\s+)?(?:void|enum\s+\w+|int|irqreturn_t|unsigned\s+long|long|u\d+|bool)[ \t\*]+'+re.escape(name)+r'\s*\(', src)
    if not m: return None
    i = m.end()
    depth = 0; started = False
    out = []
    while i < len(src):
        c = src[i]
        if c == '{': depth += 1; started = True
        elif c == '}':
            depth -= 1
            if started and depth == 0:
                return ''.join(out)
        if started: out.append(c)
        i += 1
    return None
for cb in cbs:
    b = body(cb)
    if not b: continue
    for lm in re.finditer(r'spin_lock(?:_irqsave|_irq|_bh)?\s*\(\s*&([\w\.\>\-\>\[\]]+)', b):
        print(f"{path}\tCB={cb}\tLOCK={lm.group(1)}\tMODE={lm.group(0).split('(')[0].strip()}")
PYEOF
done > "$TMPDIR/cb_locks.txt" 2>/dev/null; sort -u "$TMPDIR/cb_locks.txt" | wc -l; sort -u "$TMPDIR/cb_locks.txt" | head -40
